import{_ as t,c as e,o,ag as i}from"./chunks/framework.DOxaYS31.js";const h=JSON.parse('{"title":"Configuration","description":"","frontmatter":{},"headers":[],"relativePath":"guide/configuration.md","filePath":"guide/configuration.md"}'),l={name:"guide/configuration.md"};function r(s,a,n,c,u,p){return o(),e("div",null,[...a[0]||(a[0]=[i('<h1 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h1><p>Complete settings and customization guide.</p><h2 id="api-provider-setup" tabindex="-1">API Provider Setup <a class="header-anchor" href="#api-provider-setup" aria-label="Permalink to &quot;API Provider Setup&quot;">​</a></h2><h3 id="openai" tabindex="-1">OpenAI <a class="header-anchor" href="#openai" aria-label="Permalink to &quot;OpenAI&quot;">​</a></h3><ol><li>Get API key: <a href="https://platform.openai.com/api-keys" target="_blank" rel="noreferrer">platform.openai.com/api-keys</a></li><li>In app Settings (⚙️): Select <strong>OpenAI</strong></li><li>Paste API key</li><li>(Optional) Change model from default <code>gpt-5-nano</code></li></ol><p><strong>Available models:</strong> gpt-4o-mini, gpt-4o, gpt-4, gpt-3.5-turbo, etc.</p><h3 id="google-gemini" tabindex="-1">Google Gemini <a class="header-anchor" href="#google-gemini" aria-label="Permalink to &quot;Google Gemini&quot;">​</a></h3><ol><li>Get API key: <a href="https://aistudio.google.com/apikey" target="_blank" rel="noreferrer">aistudio.google.com/apikey</a></li><li>In app Settings (⚙️): Select <strong>Gemini</strong></li><li>Paste API key</li><li>(Optional) Change model from default <code>gemini-2.5-flash</code></li></ol><p><strong>Available models:</strong> gemini-2.5-flash, gemini-1.5-pro, gemini-pro, etc.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Never share your API key or commit it to version control!</p></div><h2 id="custom-enhancement-options" tabindex="-1">Custom Enhancement Options <a class="header-anchor" href="#custom-enhancement-options" aria-label="Permalink to &quot;Custom Enhancement Options&quot;">​</a></h2><p>Create up to 5 custom prompts for specific needs.</p><h3 id="how-to-add" tabindex="-1">How to Add <a class="header-anchor" href="#how-to-add" aria-label="Permalink to &quot;How to Add&quot;">​</a></h3><ol><li>Settings (⚙️) → Scroll to &quot;Custom Enhancement Options&quot;</li><li>Click <strong>Add Custom Option</strong></li><li>Enter: <ul><li><strong>Label:</strong> Button name (e.g., &quot;Add Emojis&quot;)</li><li><strong>Prompt:</strong> AI instruction (e.g., &quot;Add relevant emojis&quot;)</li></ul></li><li>Click <strong>Add</strong></li></ol><h3 id="optimization-tips" tabindex="-1">Optimization Tips <a class="header-anchor" href="#optimization-tips" aria-label="Permalink to &quot;Optimization Tips&quot;">​</a></h3><p><strong>Keep prompts 2-5 words:</strong></p><ul><li>✅ &quot;Add emojis&quot;</li><li>✅ &quot;Simplify for beginners&quot;</li><li>✅ &quot;Remove jargon&quot;</li><li>❌ &quot;Please make this text more simple and easy to understand&quot;</li></ul><p><strong>Why?</strong> Shorter = Faster + Cheaper</p><h3 id="example-prompts" tabindex="-1">Example Prompts <a class="header-anchor" href="#example-prompts" aria-label="Permalink to &quot;Example Prompts&quot;">​</a></h3><ul><li>&quot;Add emojis&quot;</li><li>&quot;Simplify technical terms&quot;</li><li>&quot;Make persuasive&quot;</li><li>&quot;Add bullet points&quot;</li><li>&quot;Remove passive voice&quot;</li></ul><h2 id="token-usage-tracking" tabindex="-1">Token Usage Tracking <a class="header-anchor" href="#token-usage-tracking" aria-label="Permalink to &quot;Token Usage Tracking&quot;">​</a></h2><p>Monitor API costs in real-time.</p><h3 id="what-s-tracked" tabindex="-1">What&#39;s Tracked <a class="header-anchor" href="#what-s-tracked" aria-label="Permalink to &quot;What&#39;s Tracked&quot;">​</a></h3><ul><li>Input/output tokens per request</li><li>Estimated cost (OpenAI pricing)</li><li>Cumulative totals</li></ul><h3 id="where-to-view" tabindex="-1">Where to View <a class="header-anchor" href="#where-to-view" aria-label="Permalink to &quot;Where to View&quot;">​</a></h3><ul><li>Main window: Current session</li><li>Settings: Full history</li><li>Reset button: Clear all data</li></ul><h2 id="data-storage" tabindex="-1">Data Storage <a class="header-anchor" href="#data-storage" aria-label="Permalink to &quot;Data Storage&quot;">​</a></h2><h3 id="settings-location" tabindex="-1">Settings Location <a class="header-anchor" href="#settings-location" aria-label="Permalink to &quot;Settings Location&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>~/Library/Application Support/com.kitelus.grammar-assistant/</span></span></code></pre></div><h3 id="what-s-stored-locally" tabindex="-1">What&#39;s Stored Locally <a class="header-anchor" href="#what-s-stored-locally" aria-label="Permalink to &quot;What&#39;s Stored Locally&quot;">​</a></h3><ul><li>API keys (secure)</li><li>Provider preferences</li><li>Custom enhancement options</li><li>Token usage statistics</li></ul><h3 id="what-s-not-stored" tabindex="-1">What&#39;s NOT Stored <a class="header-anchor" href="#what-s-not-stored" aria-label="Permalink to &quot;What&#39;s NOT Stored&quot;">​</a></h3><ul><li>❌ Your text content</li><li>❌ AI responses</li><li>❌ Usage analytics</li></ul><h2 id="token-usage-tracking-1" tabindex="-1">Token Usage Tracking <a class="header-anchor" href="#token-usage-tracking-1" aria-label="Permalink to &quot;Token Usage Tracking&quot;">​</a></h2><p>Monitor your API usage and costs:</p><ul><li><strong>Real-time tracking</strong>: See tokens used per request</li><li><strong>Cost estimates</strong>: Approximate costs for OpenAI</li><li><strong>Total statistics</strong>: View cumulative usage</li><li><strong>Reset stats</strong>: Clear tracking data anytime</li></ul><p>Access from settings or view in the main interface.</p><h2 id="global-shortcut" tabindex="-1">Global Shortcut <a class="header-anchor" href="#global-shortcut" aria-label="Permalink to &quot;Global Shortcut&quot;">​</a></h2><p>The keyboard shortcut is <strong>Cmd+Shift+G</strong> (fixed, not customizable).</p><p><strong>How it works:</strong></p><ol><li>Select text in any app</li><li>Press Cmd+Shift+G</li><li>Grammar Assistant opens with your text</li><li>Choose enhancement mode</li><li>Copy and paste result back</li></ol><h2 id="privacy-data" tabindex="-1">Privacy &amp; Data <a class="header-anchor" href="#privacy-data" aria-label="Permalink to &quot;Privacy &amp; Data&quot;">​</a></h2><h3 id="data-collection" tabindex="-1">Data Collection <a class="header-anchor" href="#data-collection" aria-label="Permalink to &quot;Data Collection&quot;">​</a></h3><p>Grammar Assistant respects your privacy:</p><ul><li>✅ Text only sent when you press Cmd+Shift+G</li><li>✅ No automatic text collection</li><li>✅ No analytics or tracking</li><li>✅ API keys stored locally only</li><li>✅ No cloud storage</li></ul><h3 id="local-storage" tabindex="-1">Local Storage <a class="header-anchor" href="#local-storage" aria-label="Permalink to &quot;Local Storage&quot;">​</a></h3><p>Settings are stored at:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>~/Library/Application Support/com.kitelus.grammar-assistant/</span></span></code></pre></div>',48)])])}const g=t(l,[["render",r]]);export{h as __pageData,g as default};
